content:
{
  "findings": [
    {
      "check_id": "CKV_AWS_364",
      "title": "Ensure that AWS Lambda function permissions delegated to AWS services are limited by SourceArn or SourceAccount",
      "resource": "aws_ssm_document.pass2",
      "severity": "MEDIUM",
      "explanation": "The 'aws_ssm_document' resource 'pass2' has permissions that could be overly permissive if associated with a Lambda function or other services, though directly it doesn't apply, the account_ids should be a list."
    }
  ],
  "patched_code": "resource "aws_ssm_document" "pass2" {
  name          = "test_document"
  document_type = "Command"

  content = <<DOC
  {
    "schemaVersion": "1.2",
    "description": "Check ip configuration of a Linux instance.",
    "parameters": {

    },
    "runtimeConfig": {
      "aws:runShellScript": {
        "properties": [
          {
            "id": "0.aws:runShellScript",
            "runCommand": ["ifconfig"]
          }
        ]
      }
    }
  }
DOC
  permissions = {
    type        = "Share"
    account_ids = ["680235478471"]
  }
}
",
  "fix_summary": "The 'account_ids' attribute in the 'permissions' block of the 'aws_ssm_document' resource 'pass2' was changed to be a list by adding square brackets around the value."
}
